size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate)
{
  size_t
    bytes_written = 0;

  MagickBooleanType
    status;

  ssize_t
    y;

  unsigned char
    *pixels = NULL;

  size_t
    length = image->rows * image->columns * GetPixelChannels(image);

  pixels = AcquireMemory(length);
  if (!pixels)
    return 0;

  for (y = 0; y < (ssize_t) image->rows; y++)
  {
    Quantum
      *q;

    q = GetPixelCache(image, 0, y, image->columns, 1, 0, quantum_type);
    ExportQuantumPixels(image_info, image, NULL, quantum_type, image->columns, 1,
                        pixels + y * image->columns);
  }

  if (psd_info->compression == RLECompression)
  {
    // RLE compression logic
    length = CompressRLE(pixels, length);
    status = WriteBlobMemory(image, &length, pixels);
  }
  else if (psd_info->compression == ZipCompression)
  {
    // ZIP compression logic
    length = CompressZIP(pixels, length);
    status = WriteBlobMemory(image, &length, pixels);
  }
  else
  {
    // No compression
    status = WriteBlobMemory(image, &length, pixels);
  }

  if (status == MagickFalse)
  {
    bytes_written = 0;
    goto cleanup;
  }

  bytes_written = length;

cleanup:
  if (pixels)
    RelinquishMemory(pixels);

  return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate) {
    size_t bytes_written = 0;
    MagickBooleanType monochrome = MagickFalse;
    size_t row, rows = image->rows;
    unsigned char *pixels = NULL;
    MagickOffsetType offset = size_offset;
    size_t length;

    if (psd_info->depth == 1)
        monochrome = MagickTrue;

    pixels = (unsigned char *) AcquireMemory(image->columns * sizeof(*pixels));
    if (!pixels) {
        bytes_written = 0;
        goto cleanup;
    }

    for (row = 0; row < rows; row++) {
        ExportPixels(image, 0, row, image->columns, 1, quantum_type, (void *) pixels, MagickTrue);
        if (separate != MagickFalse)
            continue;

        switch (psd_info->compression) {
            case RLECompression:
                length = CompressRLE(pixels, image->columns, image->rows, compact_pixels);
                break;
            case ZipCompression:
                length = CompressZIP(pixels, image->columns, image->rows, compact_pixels);
                break;
            default:
                length = image->columns;
                memcpy(compact_pixels, pixels, length);
                break;
        }

        WriteBlobMemory(image, length, compact_pixels);
        bytes_written += length;
    }

    if (separate != MagickFalse) {
        for (row = 0; row < rows; row++) {
            ExportPixels(image, 0, row, image->columns, 1, quantum_type, (void *) pixels, MagickTrue);
            WriteBlobMemory(image, image->columns, pixels);
            bytes_written += image->columns;
        }
    }

    if (psd_info->compression != NoCompression)
        WriteBlobLong(image, 0);

cleanup:
    if (pixels)
        pixels = RelinquishMemory(pixels);
    return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image, QuantumType quantum_type,
                       unsigned char *compact_pixels, MagickOffsetType size_offset,
                       MagickBooleanType separate) {
    size_t bytes_written = 0;
    unsigned char *pixels = NULL;
    size_t rows = image->rows;
    size_t columns = image->columns;
    size_t depth = image->depth;
    MagickBooleanType is_monochrome = (psd_info->color_mode == MonochromeColorMode);

    pixels = (unsigned char *) AcquireMemory(columns * sizeof(unsigned char));
    if (!pixels)
        return 0;

    for (size_t y = 0; y < rows; y++) {
        for (size_t x = 0; x < columns; x++) {
            Quantum pixel = GetPixelQuantum(image, x, y, quantum_type);
            pixels[x] = ClampToQuantum(pixel);
        }

        if (psd_info->compression == RLECompression) {
            size_t compressed_length;
            unsigned char *compressed_data = CompressRLE(pixels, columns, &compressed_length);
            if (!compressed_data)
                continue;

            WriteBlobMemory(image, compressed_length, compressed_data);
            bytes_written += compressed_length;
            RelinquishMemory(compressed_data);
        }
        else if (psd_info->compression == ZipCompression) {
            size_t compressed_length;
            unsigned char *compressed_data = CompressZip(pixels, columns, &compressed_length);
            if (!compressed_data)
                continue;

            WriteBlobMemory(image, compressed_length, compressed_data);
            bytes_written += compressed_length;
            RelinquishMemory(compressed_data);
        }
        else {
            WriteBlobMemory(image, columns, pixels);
            bytes_written += columns;
        }
    }

    if (is_monochrome) {
        for (size_t y = 0; y < rows; y++) {
            for (size_t x = 0; x < columns; x++) {
                Quantum pixel = GetPixelQuantum(image, x, y, quantum_type);
                pixels[x] = ClampToQuantum(pixel);
            }

            if (psd_info->compression == RLECompression) {
                size_t compressed_length;
                unsigned char *compressed_data = CompressRLE(pixels, columns, &compressed_length);
                if (!compressed_data)
                    continue;

                WriteBlobMemory(image, compressed_length, compressed_data);
                bytes_written += compressed_length;
                RelinquishMemory(compressed_data);
            }
            else if (psd_info->compression == ZipCompression) {
                size_t compressed_length;
                unsigned char *compressed_data = CompressZip(pixels, columns, &compressed_length);
                if (!compressed_data)
                    continue;

                WriteBlobMemory(image, compressed_length, compressed_data);
                bytes_written += compressed_length;
                RelinquishMemory(compressed_data);
            }
            else {
                WriteBlobMemory(image, columns, pixels);
                bytes_written += columns;
            }
        }
    }

    RelinquishMemory(pixels);
    return bytes_written;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, QuantumType quantum_type, unsigned char *compact_pixels, MagickOffsetType size_offset, MagickBooleanType separate) {
  size_t
    count = 0;
  MagickBooleanType
    status = MagickFalse;
  register ssize_t
    x;
  ssize_t
    y;
  unsigned char
    *reductum_pixels = NULL;
  size_t
    reductum_length = 0;

  if (image->depth > 8 && (psd_info->compression == ZipCompression || psd_info->compression == RLECompression))
    image->depth = 8;

  if (image->depth <= 8)
  {
    if (image->depth < 8)
    {
      for (y = 0; y < (ssize_t) image->rows; y++)
      {
        for (x = 0; x < (ssize_t) image->columns; x++)
        {
          register Quantum
            *p;
          p = GetPixelCache(image, x, y, 1, 1, &image->exception);
          p[0] = ScaleQuantumToChar(p[0]);
        }
      }
    }
  }

  if (psd_info->compression == RLECompression)
    reductum_length = (size_t) (image->rows * image->columns * 4);

  reductum_pixels = (unsigned char *) AcquireMemory(reductum_length);
  if (reductum_pixels == (unsigned char *) NULL)
    ThrowPSDException(ResourceLimitError, "MemoryAllocationFailed", image->filename);

  for (y = 0; y < (ssize_t) image->rows; y++)
  {
    MagickBooleanType
      proceed = MagickTrue;
    register ssize_t
      i;
    register Quantum
      *p;
    size_t
      length = 0;
    ssize_t
      count_;
    unsigned char
      *pixels;

    pixels = ExportImagePixels(image, 0, y, image->columns, 1, "C", quantum_type, &image->exception);
    if (image->depth <= 8)
    {
      p = (Quantum *) pixels;
      for (i = 0; i < (ssize_t) image->columns; i++)
        pixels[i] = (unsigned char) p[i];
    }

    switch (psd_info->compression)
    {
      case RLECompression:
        count_ = RLECompress(pixels, image->columns, &reductum_pixels[length]);
        length += (size_t) count_;
        break;
      case ZipCompression:
        break;
      default:
        length = (size_t) image->columns;
        break;
    }

    count += WriteBlob(image, length, reductum_pixels);
  }

  reductum_pixels = (unsigned char *) RelinquishMemory(reductum_pixels);
  return count;
}

size_t WritePSDChannel(const PSDInfo *psd_info, const ImageInfo *image_info,
                       Image *image, Image *next_image,
                       QuantumType quantum_type, unsigned char *compact_pixels,
                       MagickOffsetType size_offset, MagickBooleanType separate) {
  size_t bytes_written = 0;
  MagickBooleanType is_monochrome = (psd_info->depth == 1 && psd_info->channels == 1);
  const size_t image_rows = image->rows;
  const size_t image_columns = image->columns;
  const size_t channel_depth = psd_info->depth;
  unsigned char *pixel_data = NULL;
  size_t row = 0;

  for (row = 0; row < image_rows; row++) {
    MagickBooleanType success;
    MagickSizeType export_length;
    unsigned char *exported_pixels;

    exported_pixels = ExportPixelRow(image, image, row, quantum_type,
                                     &export_length, &success);
    if (!success || exported_pixels == NULL)
      continue;

    switch (psd_info->compression) {
      case RLECompression:
        success = CompressRLE(exported_pixels, image_columns, channel_depth,
                              &pixel_data, &bytes_written);
        break;
      case ZipCompression:
        success = CompressZIP(exported_pixels, image_columns, channel_depth,
                              &pixel_data, &bytes_written);
        break;
      default:
        success = MagickTrue;
        pixel_data = exported_pixels;
        bytes_written = export_length;
    }

    if (success) {
      WriteBlobMemory(image, size_offset, bytes_written, pixel_data);
      size_offset += bytes_written;
    }

    if (pixel_data != exported_pixels)
      free(pixel_data);
  }

  return bytes_written;
}
